class Weapon(HybridRoot):
    TYPE_ID = TYPE_WEAPON
    _DTYPE = weapon_dtype
    _ITEMSIZE = weapon_dtype.itemsize
    _PROJ = {'Weapon': weapon_dtype}
    _OBJ_LIST_SPECS = ()
    _PRIM_COLS = ()

    def attack(self, target, amount=5):
        return Weapon__attack(self._rec('Weapon'), self._addr, *_ent_pair(target, 'Entity'), int(amount))

class Entity(HybridRoot):
    TYPE_ID = TYPE_ENTITY
    _DTYPE = entity_dtype
    _ITEMSIZE = entity_dtype.itemsize
    _PROJ = {'Entity': entity_dtype}
    _OBJ_LIST_SPECS = ()
    _PRIM_COLS = ('health',)

    @property
    def health(self):
        return self._row['health'][0].item()

    @health.setter
    def health(self, value):
        self._row['health'][0] = value

    def take_damage(self, amount):
        return Entity__take_damage(self._rec('Entity'), self._addr, int(amount))

    def __init__(self):
        self.health = 100
